#!/usr/bin/env python3
import os
import ssl
from datetime import datetime, timezone

CERT_PATH = "/app/ssl/server.crt"
KEY_PATH = "/app/ssl/server.key"


def main():
    if not os.path.isfile(CERT_PATH):
        raise SystemExit(f"Certificate not found: {CERT_PATH}")
    if not os.path.isfile(KEY_PATH):
        raise SystemExit(f"Private key not found: {KEY_PATH}")

    context = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
    try:
        context.load_cert_chain(certfile=CERT_PATH, keyfile=KEY_PATH)
    except (ssl.SSLError, OSError) as exc:
        raise SystemExit(f"Failed to load certificate: {exc}")

    cert = ssl._ssl._test_decode_cert(CERT_PATH)

    common_name = None
    for rdn in cert.get("subject", ()):
        for name, value in rdn:
            if name == "commonName":
                common_name = value

    not_after = cert.get("notAfter")
    expires = datetime.fromtimestamp(
        ssl.cert_time_to_seconds(not_after), tz=timezone.utc
    ).strftime("%Y-%m-%d")

    print(f"Common Name: {common_name}")
    print(f"Expiration Date: {expires}")
    print("Certificate verification successful")


if __name__ == "__main__":
    main()
